import{_ as t,o,c as r,a}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const u=JSON.parse('{"title":"watersort — солвер головоломки на Go","description":"Кейс watersort: поиск решения с закрытыми колбами, скрытыми цветами и очередью запросов. Восемь режимов поиска, честный перебор.","frontmatter":{"site":"pro","title":"watersort — солвер головоломки на Go","description":"Кейс watersort: поиск решения с закрытыми колбами, скрытыми цветами и очередью запросов. Восемь режимов поиска, честный перебор.","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/work/watersort"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"watersort — солвер головоломки на Go"}],["meta",{"property":"og:description","content":"Кейс watersort: поиск решения с закрытыми колбами, скрытыми цветами и очередью запросов. Восемь режимов поиска, честный перебор."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/work/watersort"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"watersort — солвер головоломки на Go"}],["meta",{"name":"twitter:description","content":"Кейс watersort: поиск решения с закрытыми колбами, скрытыми цветами и очередью запросов. Восемь режимов поиска, честный перебор."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"work/watersort.md","filePath":"work/watersort.md"}'),i={name:"work/watersort.md"};function n(l,e,c,s,d,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="watersort-—-солвер-головоломки-на-go" tabindex="-1">watersort — солвер головоломки на Go <a class="header-anchor" href="#watersort-—-солвер-головоломки-на-go" aria-label="Permalink to &quot;watersort — солвер головоломки на Go&quot;">​</a></h1><p><strong>Задача.</strong> Решить головоломку с переливанием жидкостей, когда часть колб закрыта, часть цветов скрыта, а некоторые колбы открываются только после выполнения условий.</p><p><strong>Ограничения.</strong> Состояние неполное: цвет скрыт, но известно, что он не сливается с верхним. Перебор должен учитывать незнание, а не догадываться.</p><h2 id="что-сделал" tabindex="-1">Что сделал <a class="header-anchor" href="#что-сделал" aria-label="Permalink to &quot;Что сделал&quot;">​</a></h2><p>Солвер на чистом Go, без зависимостей. Понимает:</p><ul><li>колбы на четыре слота;</li><li>доску в виде текстового файла с директивами;</li><li>скрытые слоты <code>?</code> и «известный цвет, который не переливается с верхним» <code>?з</code>;</li><li>закрытые колбы, которые открываются после N выполненных запросов;</li><li>очередь запросов с альтернативами: <code>з|тз</code> значит «зелёный или тёмно-зелёный».</li></ul><p>Восемь режимов поиска: <code>requests</code>, <code>open</code>, <code>done</code>, <code>collect</code>, <code>reveal</code>, <code>sort</code>, <code>counts</code> и проверка достижимости. Режим <code>counts</code> отдельно считает известные, скрытые и пустые слоты — это нужно, чтобы проверять разбор доски до запуска поиска.</p><h2 id="доказательство" tabindex="-1">Доказательство <a class="header-anchor" href="#доказательство" aria-label="Permalink to &quot;Доказательство&quot;">​</a></h2><ul><li><code>go build</code> и <code>go test ./...</code> без внешних зависимостей.</li><li>Разбор доски и поиск разделены, поэтому ошибка в формате не выглядит как «решения нет».</li><li>Восемь режимов покрывают реальные задачи, а не одну демо-головоломку.</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Эвристика для больших досок: сейчас честный перебор упирается в размер.</li><li>Генератор досок для проверки солвера на случайных конфигурациях.</li></ul>',11)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
